arguments.command:
python3 -u -c "
from pynwb import NWBHDF5IO
import numpy as np
io = NWBHDF5IO('/app/data/sub-m11/sub-m11_ses-03_behavior+ophys.nwb','r',load_namespaces=True)
nwb = io.read()
beh = nwb.processing['behavior']
print('=== BEHAVIOR ===')
for k,v in beh.data_interfaces.items():
    print(' ',k, type(v))
    if hasattr(v,'time_series'):
        for k2,v2 in v.time_series.items():
            print('    ',k2, v2.data.shape, v2.unit, 'ts' if v2.timestamps is not None else 'rate', v2.description[:80])
oph = nwb.processing['ophys']
print('=== OPHYS ===')
for k,v in oph.data_interfaces.items():
    print(' ',k, type(v))
    if hasattr(v,'roi_response_series'):
        for k2,v2 in v.roi_response_series.items():
            print('    ',k2, v2.data.shape, v2.unit, v2.rate if v2.rate else 'ts', v2.description[:100])
" 2>&1 | tail -40

