python3 -u -c "
from pynwb import NWBHDF5IO
import numpy as np, warnings
warnings.filterwarnings('ignore')
io=NWBHDF5IO('/app/data/sub-m17/sub-m17_ses-05_behavior+ophys.nwb','r',load_namespaces=True); nwb=io.read()
oph=nwb.processing['ophys']
for k,v in oph.data_interfaces.items():
    print(k, type(v).__name__)
    if hasattr(v,'roi_response_series'):
        for k2,r in v.roi_response_series.items():
            print('   ',k2, r.data.shape, r.rate, 'rois_table_len', len(r.rois.table.id))
    if hasattr(v,'plane_segmentations'):
        for k2,p in v.plane_segmentations.items():
            print('   PS',k2, len(p.id), p.colnames, np.unique(np.array(p['planeIdx'].data),return_counts=True))
print('imaging_planes', list(nwb.imaging_planes.keys()))
for k,v in nwb.imaging_planes.items(): print(k, v.imaging_rate, v.indicator, v.location, v.description)
"

